#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

static void skip_separators(char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r' || **p == ',') {
        (*p)++;
    }
}

static int read_value(char **p, int *is_null) {
    skip_separators(p);
    if (strncmp(*p, "null", 4) == 0) {
        *p += 4;
        *is_null = 1;
        return 0;
    }

    *is_null = 0;
    char *end;
    long v = strtol(*p, &end, 10);
    *p = end;
    return (int)v;
}

static TreeNode *new_node(int value) {
    TreeNode *node = (TreeNode *)malloc(sizeof(TreeNode));
    node->val = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static TreeNode *parse_tree(char **p) {
    skip_separators(p);
    if (**p != '[') return NULL;
    (*p)++;

    int is_null;
    int root_value = read_value(p, &is_null);
    if (is_null) return NULL;

    TreeNode **queue = (TreeNode **)malloc(10000 * sizeof(TreeNode *));
    int head = 0, tail = 0;

    TreeNode *root = new_node(root_value);
    queue[tail++] = root;

    while (head < tail) {
        skip_separators(p);
        if (**p == ']') {
            (*p)++;
            break;
        }

        TreeNode *current = queue[head++];
        int left_value = read_value(p, &is_null);
        if (!is_null) {
            current->left = new_node(left_value);
            queue[tail++] = current->left;
        }

        skip_separators(p);
        if (**p == ']') {
            (*p)++;
            break;
        }

        int right_value = read_value(p, &is_null);
        if (!is_null) {
            current->right = new_node(right_value);
            queue[tail++] = current->right;
        }
    }

    free(queue);
    return root;
}

double *averageOfLevels(TreeNode *root, int *returnSize) {
    double *result = (double *)malloc(10000 * sizeof(double));
    TreeNode **queue = (TreeNode **)malloc(10000 * sizeof(TreeNode *));
    int head = 0, tail = 0, levels = 0;

    queue[tail++] = root;
    while (head < tail) {
        int level_end = tail;
        long double sum = 0.0L;
        int count = 0;

        while (head < level_end) {
            TreeNode *node = queue[head++];
            sum += node->val;
            count++;
            if (node->left) queue[tail++] = node->left;
            if (node->right) queue[tail++] = node->right;
        }

        result[levels++] = (double)(sum / count);
    }

    free(queue);
    *returnSize = levels;
    return result;
}

static void free_tree(TreeNode *root) {
    if (!root) return;
    TreeNode **queue = (TreeNode **)malloc(10000 * sizeof(TreeNode *));
    int head = 0, tail = 0;
    queue[tail++] = root;

    while (head < tail) {
        TreeNode *node = queue[head++];
        if (node->left) queue[tail++] = node->left;
        if (node->right) queue[tail++] = node->right;
        free(node);
    }
    free(queue);
}

